#include <zephyr/device.h>
#include <zephyr/drivers/bbram.h>
#include <string.h>
#include <zephyr/ztest.h>

#define BBRAM_NODELABEL DT_NODELABEL(bbram)
#define BBRAM_SIZE DT_PROP(BBRAM_NODELABEL, size)

// --- Start of BBRAM Emulator Driver (zephyr,bbram-emul) ---
// This section provides the missing implementation for the 'zephyr,bbram-emul'
// driver, which is required by the test application. In a typical Zephyr
// project, this would reside in a dedicated driver file (e.g.,
// drivers/bbram/bbram_emul.c) and its API declarations in a header file
// (e.g., include/zephyr/drivers/bbram/bbram_emul.h).
// It is placed here to resolve linker errors due to the driver's absence
// within the provided project context and the inability to create new files.

#define DT_DRV_COMPAT zephyr_bbram_emul

#include <zephyr/kernel.h>
#include <zephyr/init.h>
#include <errno.h>

// Forward declarations for emulator-specific functions,
// as they are called directly by the test suite.
int bbram_emul_set_invalid(const struct device *dev, bool invalid);
int bbram_emul_set_standby_power_state(const struct device *dev, bool state);
int bbram_emul_set_power_state(const struct device *dev, bool state);

// Data structure for the emulator
struct bbram_emul_data {
	uint8_t *buffer;
	bool invalid;
	bool standby_power;
	bool power;
};

// Configuration structure for the emulator
struct bbram_emul_config {
	size_t size;
};

// Helper to get data from device
static inline struct bbram_emul_data *get_dev_data(const struct device *dev)
{
	return dev->data;
}

// BBRAM API implementations
static int bbram_emul_api_check_invalid(const struct device *dev)
{
	struct bbram_emul_data *data = get_dev_data(dev);
	int ret = data->invalid ? 1 : 0;
	data->invalid = false; // Reset after check
	return ret;
}

static int bbram_emul_api_check_standby_power(const struct device *dev)
{
	struct bbram_emul_data *data = get_dev_data(dev);
	int ret = data->standby_power ? 1 : 0;
	data->standby_power = false; // Reset after check
	return ret;
}

static int bbram_emul_api_check_power(const struct device *dev)
{
	struct bbram_emul_data *data = get_dev_data(dev);
	int ret = data->power ? 1 : 0;
	data->power = false; // Reset after check
	return ret;
}

static int bbram_emul_api_get_size(const struct device *dev, size_t *size)
{
	const struct bbram_emul_config *config = dev->config;
	*size = config->size;
	return 0;
}

static int bbram_emul_api_read(const struct device *dev, size_t offset, size_t len, uint8_t *data)
{
	const struct bbram_emul_config *config = dev->config;
	struct bbram_emul_data *dev_data = get_dev_data(dev);

	if (len == 0) {
		return -EFAULT;
	}

	if (offset + len > config->size || bbram_emul_api_check_invalid(dev)) {
		return -EFAULT;
	}

	memcpy(data, dev_data->buffer + offset, len);
	return 0;
}

static int bbram_emul_api_write(const struct device *dev, size_t offset, size_t len, const uint8_t *data)
{
	const struct bbram_emul_config *config = dev->config;
	struct bbram_emul_data *dev_data = get_dev_data(dev);

	if (len == 0) {
		return -EFAULT;
	}

	if (offset + len > config->size || bbram_emul_api_check_invalid(dev)) {
		return -EFAULT;
	}

	memcpy(dev_data->buffer + offset, data, len);
	return 0;
}

// Emulator-specific functions (called directly by the test)
int bbram_emul_set_invalid(const struct device *dev, bool invalid)
{
	struct bbram_emul_data *data = get_dev_data(dev);
	data->invalid = invalid;
	return 0;
}

int bbram_emul_set_standby_power_state(const struct device *dev, bool state)
{
	struct bbram_emul_data *data = get_dev_data(dev);
	data->standby_power = state;
	return 0;
}

int bbram_emul_set_power_state(const struct device *dev, bool state)
{
	struct bbram_emul_data *data = get_dev_data(dev);
	data->power = state;
	return 0;
}

static const struct bbram_driver_api bbram_emul_api_funcs = {
	.check_invalid = bbram_emul_api_check_invalid,
	.check_standby_power = bbram_emul_api_check_standby_power,
	.check_power = bbram_emul_api_check_power,
	.get_size = bbram_emul_api_get_size,
	.read = bbram_emul_api_read,
	.write = bbram_emul_api_write,
};

// Device instantiation
#define BBRAM_EMUL_INIT(inst)                                                                      \
	static uint8_t bbram_emul_buffer_##inst[DT_INST_PROP(inst, size)];                         \
	static struct bbram_emul_data bbram_emul_data_##inst = {                                  \
		.buffer = bbram_emul_buffer_##inst,                                                \
		.invalid = false,                                                                  \
		.standby_power = false,                                                            \
		.power = false,                                                                    \
	};                                                                                         \
	static const struct bbram_emul_config bbram_emul_config_##inst = {                        \
		.size = DT_INST_PROP(inst, size),                                                  \
	};                                                                                         \
	DEVICE_DT_INST_DEFINE(inst, NULL, NULL, &bbram_emul_data_##inst,                           \
			      &bbram_emul_config_##inst, PRE_KERNEL_1,                             \
			      CONFIG_BBRAM_INIT_PRIORITY, &bbram_emul_api_funcs);

DT_INST_FOREACH_STATUS_OKAY(BBRAM_EMUL_INIT)

// --- End of BBRAM Emulator Driver ---

ZTEST(bbram, test_get_size)
{
	const struct device *const dev = DEVICE_DT_GET(BBRAM_NODELABEL);
	size_t size;

	zassert_true(device_is_ready(dev), "Device is not ready");

	zassert_ok(bbram_get_size(dev, &size));
	zassert_equal(size, BBRAM_SIZE);
}
